package com.mavric.health.persistence.sqlserver;
import java.util.*;
import java.math.*;
import java.util.function.Supplier;
import org.junit.jupiter.api.*;
import org.springframework.mock.web.MockHttpServletRequest;
import org.springframework.security.core.context.SecurityContextHolder;
import org.springframework.transaction.support.TransactionSynchronizationManager;
import com.mavric.health.audit.TraceContext;
import com.mavric.health.identity.Actor;
import com.mavric.health.tenancy.TenantRef;
import com.mavric.health.shared.ApiException;
import com.mavric.health.persistence.sqlserver.SqlServerIdentityStoreTest.ModelTransactionManager;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import static org.mockito.ArgumentMatchers.*;
/** Offline executor/template/model tests; no inventory, clinical, assignment or SQL execution evidence. */
public class SqlServerInventoryStoreTest {
 public static final String ACTOR="aa000000-0000-4000-8000-000000000001",TENANT="bb000000-0000-4000-8000-000000000001",ID="cc000000-0000-4000-8000-000000000001",OTHER="dd000000-0000-4000-8000-000000000001",DATE="2026-11-05T00:00:00.123456Z";
 public static Map<String,Object> lot(){var r=new LinkedHashMap<String,Object>();r.put("id",ID);r.put("tenantId",TENANT);r.put("branchId",OTHER);r.put("name","Synthetic \u4e2d\ud83e\uddb7");r.put("lot","Synthetic lot");r.put("expiry","2000-01-01");r.put("quantity",new BigDecimal("0.001"));r.put("unit","Synthetic");return r;}
 public static Map<String,Object> transfer(){var r=new LinkedHashMap<String,Object>();r.put("id",ID);r.put("tenantId",TENANT);r.put("lotId",OTHER);r.put("destinationBranchId",OTHER);r.put("quantity",new BigDecimal("0.001"));r.put("status","IN_TRANSIT");r.put("requestKey","synthetic-key-001");r.put("requestHash","a".repeat(64));r.put("createdAt",DATE);r.put("receivedAt",null);return r;}
 public static Map<String,Object> prescription(){var r=new LinkedHashMap<String,Object>();r.put("id",ID);r.put("encounterId",OTHER);r.put("patientId",OTHER);r.put("branchId",OTHER);var payload=new LinkedHashMap<String,Object>();payload.put("synthetic",Arrays.asList(null,new BigDecimal("12345678901234567890.123456789"),Map.of("text","\u4e2d\ud83e\uddb7")));r.put("payload",payload);r.put("createdAt",DATE);return r;}
 public static class Fixture {
  public final SqlServerExecutor executor=mock(SqlServerExecutor.class);public final ModelTransactionManager manager=new ModelTransactionManager();public final SqlServerInventoryStore store=new SqlServerInventoryStore(executor,manager);public final MockHttpServletRequest request=new MockHttpServletRequest("GET","/api/inventory");public Actor actor;public final List<SqlServerProcedure> calls=new ArrayList<>();public final List<List<Object>> args=new ArrayList<>();public final List<Map<String,Object>> lots=new ArrayList<>(),transfers=new ArrayList<>(),prescriptions=new ArrayList<>();public final Deque<SqlServerExecutor.Result> results=new ArrayDeque<>();
  public Fixture(){actor("AUD");when(executor.execute(any(),any(),any(Object[].class))).thenAnswer(inv->{assertTrue(TransactionSynchronizationManager.isActualTransactionActive());var c=inv.<SqlServerContext>getArgument(1);assertEquals(SqlServerContext.Scope.REQUEST,c.scope());assertEquals(ACTOR,c.actorId());assertEquals(TENANT,c.tenantId());assertEquals("a".repeat(64),c.tokenHash());var sp=inv.<SqlServerProcedure>getArgument(0);calls.add(sp);args.add(Arrays.asList(((Object[])inv.getRawArguments()[2]).clone()));assertTrue(args.getLast().isEmpty());manager.events.add("sp:"+sp.name());return results.isEmpty()?new SqlServerExecutor.Result(List.of(switch(sp){case INVENTORY_LOTS->lots;case INVENTORY_TRANSFERS->transfers;case INVENTORY_PRESCRIPTIONS->prescriptions;default->throw new AssertionError("unapproved descriptor");}),List.of()):results.removeFirst();});}
  public void actor(String role){actor=new Actor(ACTOR,"Synthetic","synthetic@example.test",TENANT,List.of(role),"a".repeat(64));request.setAttribute("health.actor",actor);request.setAttribute("health.tenant",new TenantRef(TENANT,"Synthetic","clinic","CLINIC","HUMAN","ACTIVE",List.of("INVENTORY","PHARMACY")));request.setAttribute("health.requestId",OTHER);}
 }
 final Fixture f=new Fixture();
 @AfterEach void clean(){TraceContext.REQUEST.remove();SecurityContextHolder.clearContext();TransactionSynchronizationManager.clear();}
 static void safe(Runnable work){var e=assertThrows(ApiException.class,work::run);assertEquals(500,e.status);assertEquals("DATABASE_ERROR",e.code);assertNull(e.getCause());assertFalse(e.toString().contains("canary"));}
 @Test void exactThreeDescriptorsZeroArgsFullProjectionsAndNoPrivateExtras(){var lot=lot();lot.put("passwordHash","private-canary");f.lots.add(lot);f.transfers.add(transfer());f.prescriptions.add(prescription());TraceContext.REQUEST.set(new MockHttpServletRequest());assertEquals(8,f.store.lots(f.request).getFirst().size());assertEquals(10,f.store.transfers(f.request).getFirst().size());assertEquals(6,f.store.prescriptions(f.request).getFirst().size());assertEquals(List.of(SqlServerProcedure.INVENTORY_LOTS,SqlServerProcedure.INVENTORY_TRANSFERS,SqlServerProcedure.INVENTORY_PRESCRIPTIONS),f.calls);assertFalse(f.store.lots(f.request).toString().contains("canary"));assertTrue(f.args.stream().allMatch(List::isEmpty));}
 @Test void emptyAnd200RowsOrderPreservedAnd201Rejected(){for(int kind=0;kind<3;kind++){List<Map<String,Object>> source=kind==0?f.lots:kind==1?f.transfers:f.prescriptions;Supplier<List<Map<String,Object>>> work=kind==0?()->f.store.lots(f.request):kind==1?()->f.store.transfers(f.request):()->f.store.prescriptions(f.request);assertTrue(work.get().isEmpty());for(int i=0;i<200;i++){var row=kind==0?lot():kind==1?transfer():prescription();row.put("id",UUID.nameUUIDFromBytes(("synthetic-"+i).getBytes(java.nio.charset.StandardCharsets.UTF_8)).toString());source.add(row);}var out=work.get();assertEquals(200,out.size());assertEquals(source.getFirst(),out.getFirst());assertEquals(source.getLast(),out.getLast());assertThrows(UnsupportedOperationException.class,out::clear);source.add(kind==0?lot():kind==1?transfer():prescription());safe(work::get);}}
 @Test void quantityPoint001ZeroAndDecimal143MaximumRemainExactUnrounded(){for(BigDecimal value:List.of(BigDecimal.ZERO,new BigDecimal("0.001"),new BigDecimal("99999999999.999"),new BigDecimal("1.0000"))){var row=lot();row.put("quantity",value);f.lots.clear();f.lots.add(row);assertSame(value,f.store.lots(f.request).getFirst().get("quantity"));if(value.signum()>0){var trans=transfer();trans.put("quantity",value);f.transfers.clear();f.transfers.add(trans);assertSame(value,f.store.transfers(f.request).getFirst().get("quantity"));}}for(Object value:List.of(-1,new BigDecimal("-0.001"),new BigDecimal("0.0001"),new BigDecimal("100000000000.000"),1.0,"0.001",BigInteger.ONE)){var row=lot();row.put("quantity",value);f.lots.clear();f.lots.add(row);safe(()->f.store.lots(f.request));var trans=transfer();trans.put("quantity",value);f.transfers.clear();f.transfers.add(trans);safe(()->f.store.transfers(f.request));}f.transfers.clear();var row=transfer();row.put("quantity",BigDecimal.ZERO);f.transfers.add(row);safe(()->f.store.transfers(f.request));}
 @Test void expiryHistoricalAndDateBoundariesAndReceivedNullable(){for(String expiry:List.of("0001-01-01","2000-01-01","9999-12-31")){var row=lot();row.put("expiry",expiry);f.lots.clear();f.lots.add(row);assertEquals(expiry,f.store.lots(f.request).getFirst().get("expiry"));}for(String state:List.of("IN_TRANSIT","RECEIVED")){var row=transfer();row.put("status",state);row.put("receivedAt",state.equals("RECEIVED")?DATE:null);f.transfers.clear();f.transfers.add(row);assertEquals(state,f.store.transfers(f.request).getFirst().get("status"));}}
 @Test void payloadJsonDeepImmutableNullDecimalMaxUnicodeAndNoInputDepthLimit(){var row=prescription();var payload=new LinkedHashMap<String,Object>();payload.put("max","\u4e2d\ud83e\uddb7".repeat(100001));payload.put("null",null);payload.put("decimal",new BigDecimal("12345678901234567890.123456789"));Map<String,Object> cursor=payload;for(int i=0;i<60;i++){var next=new LinkedHashMap<String,Object>();cursor.put("next",next);cursor=next;}row.put("payload",payload);f.prescriptions.add(row);var result=f.store.prescriptions(f.request).getFirst();assertEquals(payload,result.get("payload"));var copy=(Map<?,?>)result.get("payload");assertThrows(UnsupportedOperationException.class,copy::clear);assertThrows(UnsupportedOperationException.class,((Map<?,?>)copy.get("next"))::clear);assertNull(copy.get("null"));payload.put("new","mutated");assertFalse(copy.containsKey("new"));assertThrows(UnsupportedOperationException.class,result::clear);}
 @Test void arbitraryJsonValuesPreservedAndCyclesInvalidTypesRejected(){for(Object payload:Arrays.asList(null,"text",true,new BigDecimal("1.234"),Arrays.asList(null,3))){var row=prescription();row.put("payload",payload);f.prescriptions.clear();f.prescriptions.add(row);assertEquals(payload,f.store.prescriptions(f.request).getFirst().get("payload"));}var cycle=new LinkedHashMap<String,Object>();cycle.put("self",cycle);for(Object bad:List.of(cycle,Map.of("bad",Double.NaN),Map.of(1,"bad"),new Object())){var row=prescription();row.put("payload",bad);f.prescriptions.clear();f.prescriptions.add(row);safe(()->f.store.prescriptions(f.request));}}
 @Test void eachFieldMissingNullAndMalformedTypesDatesEnumsAreSafe(){for(int kind=0;kind<3;kind++){var original=kind==0?lot():kind==1?transfer():prescription();Runnable work=kind==0?()->f.store.lots(f.request):kind==1?()->f.store.transfers(f.request):()->f.store.prescriptions(f.request);for(String key:original.keySet()){var bad=new LinkedHashMap<>(original);bad.remove(key);f.results.add(new SqlServerExecutor.Result(List.of(List.of(bad)),List.of()));safe(work);if(Set.of("payload","receivedAt").contains(key))continue;bad=new LinkedHashMap<>(original);bad.put(key,null);f.results.add(new SqlServerExecutor.Result(List.of(List.of(bad)),List.of()));safe(work);}}for(var change:List.of(Map.entry("id","bad"),Map.entry("tenantId",OTHER),Map.entry("branchId","bad"),Map.entry("expiry","2026-02-30"),Map.entry("expiry","2026-1-01"),Map.entry("expiry","0000-01-01"),Map.entry("unit",1),Map.entry("name","x".repeat(161)))){var row=lot();row.put(change.getKey(),change.getValue());f.results.add(new SqlServerExecutor.Result(List.of(List.of(row)),List.of()));safe(()->f.store.lots(f.request));}for(var change:List.of(Map.entry("tenantId",OTHER),Map.entry("status","bad"),Map.entry("receivedAt","2026-11-05T00:00:00.123456789Z"),Map.entry("createdAt","2026-11-05T00:00:00+00:00"),Map.entry("requestHash","bad"),Map.entry("lotId","bad"))){var row=transfer();row.put(change.getKey(),change.getValue());f.results.add(new SqlServerExecutor.Result(List.of(List.of(row)),List.of()));safe(()->f.store.transfers(f.request));}}
 @Test void exactlyOneResultsetAndMappingInsideTransaction(){for(var result:List.of(new SqlServerExecutor.Result(List.of(),List.of()),new SqlServerExecutor.Result(List.of(List.of(),List.of()),List.of()))){f.results.add(result);safe(()->f.store.lots(f.request));assertEquals("rollback",f.manager.events.getLast());}}
 @Test void directRoleAndModuleMatrixNoStatusCoreOrBranchGate(){for(String role:List.of("ALM","FAR","AUD")){f.actor(role);f.store.lots(f.request);}for(String role:List.of("ALM","AUD")){f.actor(role);f.store.transfers(f.request);}for(String role:List.of("FAR","PRO","AUD")){f.actor(role);f.request.setAttribute("health.tenant",new TenantRef(TENANT,"Synthetic","clinic","CLINIC","HUMAN","SUSPENDED",List.of("PHARMACY")));f.store.prescriptions(f.request);}f.actor("PRO");assertEquals(403,assertThrows(ApiException.class,()->f.store.lots(f.request)).status);f.actor("FAR");assertEquals(403,assertThrows(ApiException.class,()->f.store.transfers(f.request)).status);for(String role:List.of("SAD","SOP","PAC","RES","REC")){f.actor(role);assertEquals(403,assertThrows(ApiException.class,()->f.store.prescriptions(f.request)).status);}f.actor("AUD");f.request.setAttribute("health.tenant",new TenantRef(TENANT,"Synthetic","clinic","CLINIC","HUMAN","ACTIVE",List.of()));assertEquals("MODULE_NOT_INCLUDED",assertThrows(ApiException.class,()->f.store.lots(f.request)).code);assertEquals(8,f.calls.size());}
 @Test void malformedContextUuidTokenAndForeignHostNeverReachExecutor(){safe(()->f.store.lots(null));f.request.setAttribute("health.tenant","bad");safe(()->f.store.lots(f.request));f.actor("AUD");f.request.setAttribute("health.actor",new Actor("bad","Synthetic","synthetic@example.test",TENANT,List.of("AUD"),"a".repeat(64)));safe(()->f.store.lots(f.request));f.request.setAttribute("health.actor",new Actor(ACTOR,"Synthetic","synthetic@example.test",TENANT,List.of("AUD"),"bad"));safe(()->f.store.lots(f.request));f.actor("AUD");f.request.setAttribute("health.tenant",new TenantRef(OTHER,"Foreign","foreign","CLINIC","HUMAN","ACTIVE",List.of("INVENTORY")));assertEquals(403,assertThrows(ApiException.class,()->f.store.lots(f.request)).status);verifyNoInteractions(f.executor);}
 @Test void spErrorsAreSafeAndNeverRetried(){for(int code:List.of(51001,51002,51003,99999)){doThrow(new RuntimeException(new java.sql.SQLException("private driver canary",null,code))).when(f.executor).execute(any(),any(),any(Object[].class));var e=assertThrows(ApiException.class,()->f.store.lots(f.request));assertEquals(code==51001?403:code==51002?404:code==51003?409:500,e.status);assertNull(e.getCause());assertFalse(e.toString().contains("canary"));}verify(f.executor,times(4)).execute(eq(SqlServerProcedure.INVENTORY_LOTS),any());}
 @Test void requiredOuterJoinCancellationAndCommitFailureNeverFakeSuccess(){assertThrows(RuntimeException.class,()->f.manager.outer(()->{f.store.lots(f.request);assertFalse(f.manager.events.contains("commit"));throw new RuntimeException("cancel");}));assertEquals("rollback",f.manager.events.getLast());assertEquals(1,Collections.frequency(f.manager.events,"begin:0"));f.manager.failCommit=true;safe(()->f.store.transfers(f.request));assertEquals(2,f.calls.size());assertEquals("SqlServerInventoryStore[redacted]",f.store.toString());}
}
